// === Tab: sketch.js ===
// Thanks to Zaron Chen for the awesome code.
// Modification by Erik Oveson, to make it text-based rather than noise. 

// Reaction-Diffusion © 2024-05-15 by Zaron Chen is licensed under the MIT License. See LICENSE for more details.
//
// Interaction
// - Mouse Drag: Interact with the canvas by dragging the mouse
// - Space Bar: Press the space bar to toggle between a black and white cursor
//
// References
// The implementation is based on these videos:
// - noones img - Reaction-diffusion in 20 seconds (Touchdesginer tutorial): https://www.youtube.com/watch?v=CzmRMKQBMSw
// - ArtOfSoulburn - Reaction Diffusion In Photoshop: https://www.youtube.com/watch?v=I6Vh_NOy70M
// - SkyBase - Tutorial: Reaction-Diffusion in Photoshop: https://vimeo.com/61154654

import { mountFlex } from "https://cdn.jsdelivr.net/npm/p5.flex@0.2.0/src/p5.flex.mjs"
import { BLUR, UNSHARP, VERT } from "./shader.js"

p5.disableFriendlyErrors = true
mountFlex(p5)

new p5((p) => {
	const [WIDTH, HEIGHT] = [600, 600]
	const PIXEL_DENSITY = 1
	const TEXEL_SIZE = [1 / (WIDTH * PIXEL_DENSITY), 1 / (HEIGHT * PIXEL_DENSITY)]
	const RENDERER = p.WEBGL
	const MIN_SIDE = p.min(WIDTH, HEIGHT)

	let cnv, gfx, img
	let BlurPass, UnsharpPass
	let CURSOR_COLOR = 255
	let font

	let typedText = "";
	const MARGIN_X = 50
	let TEXT_X = -WIDTH/2 + MARGIN_X
	let TEXT_Y = 0
	let cursorX = TEXT_X
	let cursorY = TEXT_Y

	let lastTypeTime = 0;
	const TIME_TO_RESET = 1500;

	p.preload = () => {
		  font = p.loadFont('https://cdnjs.cloudflare.com/ajax/libs/topcoat/0.8.0/font/SourceCodePro-Regular.otf')
	}

	p.setup = () => {
		cnv = p.createCanvas(WIDTH, HEIGHT, RENDERER)
		p.flex({ container: { padding: "20px" }, canvas: { fit: p.SCALE_DOWN } })
		p.pixelDensity(PIXEL_DENSITY)

		gfx = p.createGraphics(WIDTH, HEIGHT, p.WEBGL)

		BlurPass = p.createShader(VERT, BLUR)
		UnsharpPass = p.createShader(VERT, UNSHARP)

		RENDERER === p.WEBGL && p.rectMode(p.CENTER)
		RENDERER === p.WEBGL && p.imageMode(p.CENTER)

		p.background(0)
		p.noStroke()
		gfx.noStroke()

		p.textFont(font)

		for (let _ = 0; _ < 3; _++) p.draw()
		cnv.elt.setAttribute("tabindex", "0");  // Make it focusable
  	cnv.elt.focus();

		cnv.elt.addEventListener("click", (event) => {
			mouseClicked(event.offsetX, event.offsetY)
		});

		cnv.elt.addEventListener("dblclick", (event) => {
			mouseDoubleClicked(event.offsetX, event.offsetY)
		});

	}

	p.draw = () => {
		ReactionDiffusion()
	}

	function mouseClicked(x, y) {
		TEXT_X = x - p.width / 2;
		TEXT_Y = y - p.height / 2;
		cursorX = TEXT_X
		cursorY = TEXT_Y
	}

	function mouseDoubleClicked(x, y) {
		clearScreen()
	}

	function clearScreen() {
		p.fill(255 - CURSOR_COLOR)
		p.rect(0, 0, WIDTH, HEIGHT)
	}

	p.keyPressed = () => {
		if (p.keyCode === p.DELETE || p.keyCode === p.BACKSPACE) {
			clearScreen()
		} else if (p.key === '/') {
			CURSOR_COLOR = 255 - CURSOR_COLOR
		}
	}

	p.keyTyped = () => {
 		p.push();
		if (p.key === '/')
			return;
		if (Date.now() - lastTypeTime > TIME_TO_RESET) {
			cursorX = TEXT_X;
			cursorY = TEXT_Y;
		}
		const charHeight = 86;
		p.textSize(charHeight);

		const char = p.key;
		const charWidth = p.textWidth(char);
		const paddingY = 36;
		const paddingX = 0;
		const textAdjust = 13;
		const charPadding = 5;
		const lineHeight = charHeight + paddingY;

		// Background box behind letter
		p.rectMode(p.CORNERS)
		p.fill(255 - CURSOR_COLOR);
		p.rect(cursorX - paddingX-charWidth/2+charPadding, cursorY-charHeight/2-paddingY/2, cursorX+charWidth/2+paddingX, cursorY+charHeight+paddingY/2);

		// Foreground letter
		p.textAlign(p.CENTER, p.CENTER)
		p.fill(CURSOR_COLOR);
		p.text(char, cursorX, cursorY);

		// Advance position
		cursorX += charWidth + charPadding;
		if (cursorX > WIDTH / 2 - MARGIN_X) {
			cursorX = -WIDTH / 2 + MARGIN_X; // back to left
			cursorY += lineHeight;           // move down a line
		} 
		if (cursorY > HEIGHT/2) {
			cursorX = TEXT_X
			cursorY = TEXT_Y
		}

		lastTypeTime = Date.now();
		p.pop();
	};

	const ReactionDiffusion = () => {
		gfx.shader(BlurPass)
		BlurPass.setUniform("texelSize", TEXEL_SIZE)
		BlurPass.setUniform("tex0", cnv)
		BlurPass.setUniform("direction", [1, 0])
		gfx.quad(-1, 1, 1, 1, 1, -1, -1, -1)

		gfx.shader(BlurPass)
		BlurPass.setUniform("texelSize", TEXEL_SIZE)
		BlurPass.setUniform("tex0", gfx)
		BlurPass.setUniform("direction", [0, 1])
		gfx.quad(-1, 1, 1, 1, 1, -1, -1, -1)

		gfx.shader(UnsharpPass)
		UnsharpPass.setUniform("texelSize", TEXEL_SIZE)
		UnsharpPass.setUniform("tex0", gfx)
		gfx.quad(-1, 1, 1, 1, 1, -1, -1, -1)

		p.image(gfx, 0, 0)
	}
})


// === Tab: shader.js ===
import * as Shox from "https://cdn.jsdelivr.net/npm/shox@1.2.0/src/Shox.js"

export const BLUR = `#version 300 es
	precision highp float;

	uniform sampler2D tex0;
	uniform vec2 texelSize;
	uniform vec2 direction;

	${Shox.blur(3)}

	in vec2 vTexCoord;
	out vec4 fragColor;
	void main() { fragColor = blur(vTexCoord, tex0, texelSize, direction); }
`

export const UNSHARP = `#version 300 es
	precision mediump float;

	uniform sampler2D tex0;
	uniform vec2 texelSize;

	${Shox.unsharp}

	in vec2 vTexCoord;
	out vec4 fragColor;
	void main() { 
		vec4 original = texture(tex0, vTexCoord);
		vec4 sharpened = unsharp(vTexCoord, tex0, texelSize*7., 64.); 
		fragColor = mix(original, sharpened, 0.5);
	}
`

export const VERT = `#version 300 es

	in vec4 aPosition;
	in vec2 aTexCoord;

	out vec2 vTexCoord;

	void main() {
		vTexCoord = aTexCoord;
		gl_Position = aPosition;
	}
`


